#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Run from the repo root, so npx finds this repo's wrangler and gh finds the repo.
cd "$(dirname "$0")/.."

# The wizard keeps only public values here; they go into wrangler.jsonc.
# Secrets, and the Developer list, go straight to Cloudflare or GitHub.
mkdir -p .wrangler
ENV_FILE=".wrangler/installation.env"

# The Installation's hostnames come from its configuration.
PLATFORM_HOST=$(sed -n 's/.*"pattern": "\([^"/]*\)".*/\1/p' wrangler.jsonc | head -n1)
APPS_DOMAIN=$(sed -n 's/.*"APPS_DOMAIN": "\([^"]*\)".*/\1/p' wrangler.jsonc | head -n1)
PLATFORM_ZONE="${PLATFORM_HOST#*.}"
if [[ -z "$PLATFORM_HOST" || -z "$APPS_DOMAIN" ]]; then
  printf 'wrangler.jsonc needs the platform route and APPS_DOMAIN set first.\n' >&2
  exit 1
fi
for tool in npx gh curl; do
  command -v "$tool" >/dev/null || { printf 'This wizard needs %s.\n' "$tool" >&2; exit 1; }
done
gh auth status >/dev/null 2>&1 || { printf 'Sign gh in first: gh auth login\n' >&2; exit 1; }

# secret_is_set NAME: whether the Worker already has that secret.
secret_is_set() { npx wrangler secret list 2>/dev/null | grep -q "\"$1\""; }

TOTAL_STAGES=10

banner "Jigworks: set up the Installation at $PLATFORM_HOST"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Trademark search"
say "Before buying domains, check that nobody holds \"Jigworks\" as a trade mark for software."
open_url "https://trademarks.ipo.gov.uk/ipo-tmtext"
step "UK IPO: search the text \"Jigworks\". Note any live mark in classes 9 or 42 (software)."
open_url "https://tmsearch.uspto.gov/search/search-information"
step "USPTO: search \"Jigworks\" the same way."
if ! confirm "Is the name clear to use?"; then
  warn "Stopping here. Nothing has been bought or created."
  exit 1
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: Workers Paid and wrangler"
open_url "https://dash.cloudflare.com/?to=/:account/workers/plans"
step "Sign in to (or create) the Cloudflare account for Jigworks, with two-factor sign-in on."
step "On Workers & Pages → Plans, choose Workers Paid (5 USD a month). Dynamic Workers need it."
pause "Press Enter once Workers Paid is active."
if npx wrangler whoami 2>/dev/null | grep -q 'You are logged in'; then
  note "wrangler is already signed in."
else
  say "Now sign wrangler in to that account with a device code: wrangler shows a link and a"
  say "code. Open the link on any device, check the code matches, and allow access."
  npx wrangler login --device
fi
npx wrangler whoami
step "Copy the Account ID of the Jigworks account from the table above."
ask CLOUDFLARE_ACCOUNT_ID "Paste the Account ID:"
if [[ ! "$CLOUDFLARE_ACCOUNT_ID" =~ ^[0-9a-f]{32}$ ]]; then
  warn "That doesn't look like an account ID (32 hex characters). Check it before going on."
fi
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
# Every wrangler command from here on uses this account.
export CLOUDFLARE_ACCOUNT_ID

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Buy $PLATFORM_ZONE and $APPS_DOMAIN"
say "The platform lives on $PLATFORM_HOST and the apps on *.$APPS_DOMAIN (ADR 0012)."
say "Cloudflare Registrar sells at cost and puts both on Cloudflare's DNS in this account."
open_url "https://dash.cloudflare.com/?to=/:account/registrar/register"
step "Search for $PLATFORM_ZONE, add it to the cart; do the same for $APPS_DOMAIN."
step "Turn on auto-renew, then check out."
warn "Buying a domain costs money and can't be undone."
pause "Press Enter once both are bought."
for zone in "$PLATFORM_ZONE" "$APPS_DOMAIN"; do
  if ! command -v dig >/dev/null; then
    note "Install dig to check $zone's nameservers; the wizard carries on."
  elif dig +short NS "$zone" | grep -q 'ns.cloudflare.com'; then
    printf '  %s✓%s %s uses Cloudflare nameservers\n' "$GREEN" "$RESET" "$zone"
  else
    warn "$zone doesn't show Cloudflare nameservers yet. New domains can take a few minutes; the wizard carries on."
  fi
done
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Zero Trust team"
say "Cloudflare Access signs people in to the platform and to apps."
open_url "https://one.dash.cloudflare.com/"
step "Choose a team name, such as \"jigworks\". It becomes <team>.cloudflareaccess.com."
step "Pick the Zero Trust Free plan. It asks for payment details but doesn't charge."
step "Then Integrations → Identity providers → Add new identity provider → One-time PIN."
note "One-time PIN emails a code to sign in. You can add GitHub or Google later."
ask ACCESS_TEAM_DOMAIN "Team domain (such as jigworks.cloudflareaccess.com):"
ACCESS_TEAM_DOMAIN="${ACCESS_TEAM_DOMAIN#https://}"; ACCESS_TEAM_DOMAIN="${ACCESS_TEAM_DOMAIN%/}"
if curl -fsS "https://$ACCESS_TEAM_DOMAIN/cdn-cgi/access/certs" | grep -q '"keys"'; then
  printf '  %s✓%s %s publishes its signing keys\n' "$GREEN" "$RESET" "$ACCESS_TEAM_DOMAIN"
else
  warn "Couldn't read https://$ACCESS_TEAM_DOMAIN/cdn-cgi/access/certs. Check the team domain."
fi
write_env ACCESS_TEAM_DOMAIN "$ACCESS_TEAM_DOMAIN"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "The Developer list"
say "Who may sign in to the platform: emails, and @domain entries for everyone at a domain."
say "Access lets them in first and the platform checks the list after, so both need it."
note "A secret can't be read back, so give the whole list, even on a re-run."
DEVELOPER_LIST=""
while [[ -z "$DEVELOPER_LIST" ]]; do
  read -r -p "  ${BOLD}Developer list (comma-separated, such as you@example.com):${RESET} " DEVELOPER_LIST
  DEVELOPER_LIST="${DEVELOPER_LIST// /}"
done
note "It becomes a Worker secret at stage 8. The wizard doesn't save it anywhere else."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Access application for the platform"
open_url "https://one.dash.cloudflare.com/"
step "Access controls → Applications → Create new application → Self-hosted and private."
step "Name it \"Jigworks platform\". Add public hostname: subdomain ${PLATFORM_HOST%%.*}, domain $PLATFORM_ZONE."
step "Access policies: create \"Jigworks Developers\", action Allow, including everyone on the list:"
note "  Emails → each email on the list: $DEVELOPER_LIST"
note "  Emails ending in → each @domain entry, if there are any."
step "Create it. Then Configure → Advanced settings → Cookie settings: set SameSite to Lax, turn HTTP Only on, and Save."
note "Lax stops apps sending requests with your sign-in (ADR 0012); HTTP Only keeps scripts from reading it."
step "Copy the Application Audience (AUD) Tag (Configure → Additional settings)."
ask ACCESS_AUD "Paste the platform's AUD tag:"
[[ "$ACCESS_AUD" =~ ^[0-9a-f]{64}$ ]] || warn "An AUD tag is usually 64 hex characters. Check it."
write_env ACCESS_AUD "$ACCESS_AUD"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Access application and DNS for apps"
say "Previews and Deployments live on *.$APPS_DOMAIN, behind an Access application of their own."
open_url "https://one.dash.cloudflare.com/"
step "Create another self-hosted application, \"Jigworks apps\": subdomain *, domain $APPS_DOMAIN."
step "Give it the \"Jigworks Developers\" policy for now. Ticket 10 decides who opens Deployments."
step "Copy its Application Audience (AUD) Tag."
ask APPS_ACCESS_AUD "Paste the apps' AUD tag:"
[[ "$APPS_ACCESS_AUD" =~ ^[0-9a-f]{64}$ ]] || warn "An AUD tag is usually 64 hex characters. Check it."
[[ "$APPS_ACCESS_AUD" != "$ACCESS_AUD" ]] || warn "That's the platform's AUD. Each application has its own."
write_env APPS_ACCESS_AUD "$APPS_ACCESS_AUD"
open_url "https://dash.cloudflare.com/?to=/:account/:zone/dns/records"
step "Pick the $APPS_DOMAIN zone → DNS → Records → Add record:"
step "type AAAA, name *, IPv6 address 100::, Proxy status Proxied. Save."
note "100:: is the address Cloudflare uses for hostnames that only a Worker answers."
pause "Press Enter once the record is saved."
if curl -sI "https://wizard-check.$APPS_DOMAIN/" | grep -qi 'cloudflareaccess.com'; then
  printf '  %s✓%s *.%s sends visitors to Access sign-in\n' "$GREEN" "$RESET" "$APPS_DOMAIN"
else
  warn "https://wizard-check.$APPS_DOMAIN/ didn't redirect to Access yet. DNS can take a few minutes."
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "The Worker's secrets"
say "The Worker needs the Agent's Anthropic key and the Developer list before its first deploy."
if secret_is_set ANTHROPIC_API_KEY && ! confirm "The Worker already has an Anthropic key. Replace it?"; then
  note "Keeping the Anthropic key it has."
else
  open_url "https://console.anthropic.com/settings/keys"
  step "Create a key named \"jigworks\" and copy it. Set a monthly spend limit under Settings → Limits."
  say "wrangler now asks for the key, hiding what you paste. If it offers to create the"
  say "Worker to hold the secret, say yes: the first deploy replaces it."
  npx wrangler secret put ANTHROPIC_API_KEY
fi
printf '%s' "$DEVELOPER_LIST" | npx wrangler secret put DEVELOPER_LIST
for name in ANTHROPIC_API_KEY DEVELOPER_LIST; do
  if secret_is_set "$name"; then
    printf '  %s✓%s the Worker has %s\n' "$GREEN" "$RESET" "$name"
  else
    warn "The Worker doesn't list $name. Set it with: npx wrangler secret put $name"
  fi
done
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "The deploy token for GitHub Actions"
say "Every merge to main deploys the platform from GitHub Actions with this token."
if gh secret list --env production --json name --jq '.[].name' 2>/dev/null | grep -qx CLOUDFLARE_API_TOKEN \
  && ! confirm "GitHub already has a deploy token. Replace it?"; then
  note "Keeping the deploy token GitHub has."
else
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create Token → the \"Edit Cloudflare Workers\" template."
  step "Account resources: Include → the Jigworks account."
  step "Zone resources: Include → Specific zone → $PLATFORM_ZONE, and add $APPS_DOMAIN the same way."
  step "Add one more permission: Zone → DNS → Edit, so a deploy can create $PLATFORM_HOST's record."
  step "Continue to summary → Create Token, and copy it."
  say "gh now asks for the token, hiding what you paste. It goes in the production"
  say "environment, which only main may use."
  gh secret set CLOUDFLARE_API_TOKEN --env production
  WRITTEN_SECRET+=("CLOUDFLARE_API_TOKEN (production)")
fi
set_var CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "wrangler.jsonc"
say "Everything only the Operator can do is done."
missing=()
for key in ACCESS_TEAM_DOMAIN ACCESS_AUD APPS_ACCESS_AUD; do
  grep -q "\"$key\": \"${!key}\"" wrangler.jsonc || missing+=("$key=${!key}")
done
if (( ${#missing[@]} )); then
  say "Copy these into wrangler.jsonc's vars (or ask Claude to), then merge to main to deploy:"
  for line in "${missing[@]}"; do note "  $line"; done
else
  printf '  %s✓%s wrangler.jsonc already has these Access values.\n' "$GREEN" "$RESET"
fi
pause "Press Enter for the summary."

finish
}

run_wizard "$@"; exit
